"""A ledger of shipments."""


class ShipmentLedger:
    def __init__(self, shipments=()):
        self._shipments = list(shipments)

    def shipments(self):
        """Return the shipments held (a copy, so callers cannot change the ledger)."""
        return list(self._shipments)

    def add(self, shipment):
        """Add one shipment to the ledger."""
        self.shipments().append(shipment)

    def total(self):
        """Return the total weight of the shipments held."""
        return sum(x.weight for x in self._shipments)


def group_by_route(shipments):
    """Return a dict from route to the list of shipments with that route."""
    groups = {}
    for x in shipments:
        groups.setdefault(x.route, []).append(x)
    return groups

